import{_ as t,o as s,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"2018-Mar-15 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2018-Mar-15 :: Ceph Performance Weekly","date":"2018-03-16T00:00:00.000Z","updated":"2018-03-16T00:00:00.000Z","tags":["Ceph","开发进展","技术讨论","行动计划","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-Mar-15_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2018/2018-Mar-15_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),e={name:"posts/2018/2018-Mar-15_-_-_Ceph_Performance_Weekly.md"};function l(i,r,g,a,p,_){return s(),o("div",null,[...r[0]||(r[0]=[n("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： Aaron、Robbie、Mike、Patrick、Adams、Jesse、Mark、Lu、Casey、Ricardo、Maurice等</p><p><strong>会议主题</strong>： Ceph社区开发进展、技术讨论及后续行动计划</p><p><strong>会议内容</strong>：</p><p><strong>1. 开发进展</strong></p><ul><li><strong>DeMatha补丁</strong>： 修改了不同数据类型的哈希行为，解决了用户缺失和哈希冲突问题。</li><li><strong>FUSE变更</strong>： Patrick正在审查的变更，修复了Luminous构建中未正确启用FAS RC功能的问题。</li><li><strong>CRC问题</strong>： 每隔六个月都会发现CRC问题，讨论了可能的解决方案。</li><li><strong>OSD批处理列表改进</strong>： 已合并，提高了assert效率。</li><li><strong>同步消息</strong>： 有一个减少锁意向的请求，看起来很好。</li><li><strong>丢弃操作</strong>： 线程丢弃已合并到master，周期性丢弃正在审查。</li><li><strong>优化操作跟踪器</strong>： 有一个工作正在进行中，以提高效率。</li><li><strong>移除读写互斥锁</strong>： 讨论了移除互斥锁的优化方案。</li><li><strong>单线程失败</strong>： 讨论了由于2701和2662导致的头失败问题。</li><li><strong>I/O节流器</strong>： 讨论了游戏时钟I/O节流器的等待问题。</li></ul><p><strong>2. 技术讨论</strong></p><ul><li><strong>互斥锁</strong>： 讨论了将互斥锁切换到标准库的方案，并讨论了新的Texas Tech技术。</li><li><strong>消息传递器</strong>： 讨论了多个OSD、核心、消息传递器和端口之间的组织结构。</li><li><strong>自动调优</strong>： 讨论了在BlueStore和RocksDB之间自动调整不同缓存大小的方案。</li></ul><p><strong>3. 行动计划</strong></p><ul><li><strong>测试DeMatha补丁</strong>： 在测试通过后合并到master。</li><li><strong>修复CRC问题</strong>： 找出解决方案并修复。</li><li><strong>审查FUSE变更</strong>： 审查并合并。</li><li><strong>合并OSD批处理列表改进</strong>： 已合并。</li><li><strong>审查同步消息请求</strong>： 审查并合并。</li><li><strong>合并丢弃操作</strong>： 合并线程丢弃，审查周期性丢弃。</li><li><strong>完成优化操作跟踪器</strong>： 完成工作并合并。</li><li><strong>移除读写互斥锁</strong>： 完成优化方案并合并。</li><li><strong>重新测试单线程失败</strong>： 重新测试并修复。</li><li><strong>解决I/O节流器问题</strong>： 与相关方沟通并解决问题。</li><li><strong>切换互斥锁</strong>： 完成切换互斥锁的方案并实施。</li><li><strong>研究消息传递器组织结构</strong>： 研究并确定最佳方案。</li><li><strong>实施自动调优方案</strong>： 完成测试并实施。</li></ul><p><strong>4. 其他事项</strong></p><ul><li>讨论了Ceph社区开发的其他事项，包括Scylla DB架构和Linux内核迁移。</li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了Ceph社区的开发进展、技术讨论及后续行动计划。会议内容涵盖了多个方面，包括补丁合并、技术讨论、行动计划等。会议旨在提高Ceph社区的协作效率，推动Ceph项目的发展。</p>",15)])])}const u=t(e,[["render",l]]);export{C as __pageData,u as default};
